package io.github.describeadmin.codegen;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.lang.reflect.Method;
import java.nio.file.FileSystem;
import java.nio.file.FileSystems;
import java.nio.file.Path;
import java.util.Map;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class CodegenCliMutaGate3Test {

    @TempDir
    Path tmp;

    @Test
    void displayFallsBackToTargetPathWhenRelativizeThrowsIllegalArgument() throws Exception {
        Path zip = tmp.resolve("other.zip");
        try (FileSystem zfs = FileSystems.newFileSystem(zip, Map.of("create", "true"))) {
            // A path from a different provider makes relativize throw
            // ProviderMismatchException, a subclass of IllegalArgumentException.
            Path target = zfs.getPath("/a/b.txt");
            Path outDir = tmp.resolve("out");

            Method display = CodegenCli.class.getDeclaredMethod("display", Path.class, Path.class);
            display.setAccessible(true);
            String result = (String) display.invoke(null, outDir, target);

            assertEquals("/a/b.txt", result);
        }
    }
}

package io.github.describeadmin.codegen;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.fail;

import java.io.ByteArrayOutputStream;
import java.io.PrintStream;
import java.nio.charset.StandardCharsets;
import java.security.Permission;

import org.junit.jupiter.api.Assumptions;
import org.junit.jupiter.api.Test;

class CodegenCliMutaGate4Test {

    /** Extends Error so the catch (Exception) blocks in main do not swallow it. */
    private static final class ExitCalled extends Error {
        private static final long serialVersionUID = 1L;
        final int status;

        ExitCalled(int status) {
            super("exit " + status);
            this.status = status;
        }
    }

    @SuppressWarnings("removal")
    private static final class NoExitSecurityManager extends SecurityManager {
        @Override
        public void checkPermission(Permission perm) {
            // allow everything
        }

        @Override
        public void checkPermission(Permission perm, Object context) {
            // allow everything
        }

        @Override
        public void checkExit(int status) {
            throw new ExitCalled(status);
        }
    }

    @Test
    @SuppressWarnings("removal")
    void mainExitsWithStatusReturnedByRun() {
        SecurityManager original = System.getSecurityManager();
        PrintStream originalOut = System.out;
        try {
            try {
                System.setSecurityManager(new NoExitSecurityManager());
            } catch (UnsupportedOperationException e) {
                Assumptions.abort("SecurityManager cannot be installed on this JVM");
            }
            System.setOut(new PrintStream(new ByteArrayOutputStream(), true, StandardCharsets.UTF_8));

            // No arguments: run() prints usage and returns 1, so main must call System.exit(1).
            try {
                CodegenCli.main(new String[0]);
                fail("main should have called System.exit");
            } catch (ExitCalled e) {
                assertEquals(1, e.status);
            }
        } finally {
            try {
                System.setSecurityManager(original);
            } catch (UnsupportedOperationException ignored) {
                // nothing was installed
            }
            System.setOut(originalOut);
        }
    }
}

package io.github.describeadmin.codegen;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.concurrent.TimeUnit;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class CodegenCliMutaGate5Test {

    @Test
    void mainPrintsSpecErrorMessageAndExitsWithCode2(@TempDir Path tmp) throws Exception {
        Path spec = tmp.resolve("bad.yaml");
        Files.writeString(spec, "module: demo\n", StandardCharsets.UTF_8);

        String javaBin = Path.of(System.getProperty("java.home"), "bin", "java").toString();
        ProcessBuilder pb = new ProcessBuilder(
                javaBin,
                "-cp", System.getProperty("java.class.path"),
                "io.github.describeadmin.codegen.CodegenCli",
                spec.toString());
        pb.redirectErrorStream(true);
        pb.directory(tmp.toFile());

        Process p = pb.start();
        byte[] bytes;
        try (InputStream in = p.getInputStream()) {
            bytes = in.readAllBytes();
        }
        assertTrue(p.waitFor(60, TimeUnit.SECONDS), "process timed out");
        String output = new String(bytes, StandardCharsets.UTF_8);

        assertEquals(2, p.exitValue(), "output was: " + output);
        assertTrue(output.startsWith("✗ "), "output was: " + output);
        assertTrue(output.trim().length() > 2, "output was: " + output);
    }
}

