package io.github.describeadmin.codegen;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.File;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.TimeUnit;
import org.junit.jupiter.api.Test;

class CodegenCliMutaGate7Test {

    @Test
    void mainPrintsGenericExceptionMessageAndExitsWithOne() throws Exception {
        String javaBin = System.getProperty("java.home") + File.separator + "bin" + File.separator + "java";
        String classpath = System.getProperty("java.class.path");

        // "--out" without a value triggers ArrayIndexOutOfBoundsException inside run(),
        // before the spec file is ever touched.
        ProcessBuilder pb = new ProcessBuilder(
                javaBin,
                "-Dfile.encoding=UTF-8",
                "-cp", classpath,
                "io.github.describeadmin.codegen.CodegenCli",
                "nonexistent-spec.yaml",
                "--out");
        pb.redirectErrorStream(true);
        Process process = pb.start();

        byte[] bytes = process.getInputStream().readAllBytes();
        boolean finished = process.waitFor(60, TimeUnit.SECONDS);
        if (!finished) {
            process.destroyForcibly();
        }
        assertTrue(finished, "CLI subprocess did not finish in time");

        String output = new String(bytes, StandardCharsets.UTF_8);
        assertEquals(1, process.exitValue(), "output was: " + output);
        assertTrue(output.contains("ArrayIndexOutOfBoundsException"),
                "expected exception class name in output but was: " + output);
        assertTrue(output.contains("✗ ArrayIndexOutOfBoundsException: "),
                "expected formatted error line but was: " + output);
    }
}

package io.github.describeadmin.codegen;

import org.junit.jupiter.api.Test;

import java.io.File;
import java.nio.charset.StandardCharsets;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.TimeUnit;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

class CodegenCliMutaGate8Test {

    @Test
    void mainExitsWithCodeOneOnUnexpectedException() throws Exception {
        String javaBin = Path.of(System.getProperty("java.home"), "bin", "java").toString();

        String classpath = System.getProperty("java.class.path");
        String codeSource = Path.of(CodegenCli.class.getProtectionDomain()
                .getCodeSource().getLocation().toURI()).toString();
        classpath = codeSource + File.pathSeparator + classpath;

        List<String> cmd = new ArrayList<>();
        cmd.add(javaBin);
        cmd.add("-cp");
        cmd.add(classpath);
        cmd.add("io.github.describeadmin.codegen.CodegenCli");
        // "--out" without a value triggers ArrayIndexOutOfBoundsException,
        // which is not a SpecException and so reaches the generic catch.
        cmd.add("spec.yaml");
        cmd.add("--out");

        Process p = new ProcessBuilder(cmd).redirectErrorStream(true).start();
        byte[] output = p.getInputStream().readAllBytes();
        boolean finished = p.waitFor(60, TimeUnit.SECONDS);
        if (!finished) {
            p.destroyForcibly();
        }
        assertTrue(finished, "child JVM did not finish");

        String text = new String(output, StandardCharsets.UTF_8);
        assertTrue(text.contains("ArrayIndexOutOfBoundsException"), text);
        assertEquals(1, p.exitValue(), text);
    }
}

package io.github.describeadmin.codegen;

import io.github.describeadmin.codegen.model.Layout;
import io.github.describeadmin.codegen.model.ModuleSpec;
import org.junit.jupiter.api.Test;

import java.nio.file.Path;
import java.util.List;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.assertTrue;

class CodegenCliMutaGate9Test {

    @Test
    void planPlacesJavaFilesUnderPackageDirectories() {
        ModuleSpec spec = new ModuleSpec(
                "com.example.demo",
                "product",
                "Product",
                "product",
                "Product",
                "/api/product",
                Layout.NESTED,
                "test",
                List.of());

        Path outDir = Path.of("out");
        Path frontendOut = Path.of("out", "frontend");

        Map<Path, String> files = CodegenCli.plan(spec, outDir, frontendOut);

        String entityPkg = spec.packageOf("entity");
        assertTrue(entityPkg.contains("."), "package should be dotted: " + entityPkg);

        Path expectedEntity = outDir.resolve("src/main/java")
                .resolve(entityPkg.replace('.', '/'))
                .resolve(spec.entityClass() + ".java");
        assertTrue(files.containsKey(expectedEntity),
                "expected " + expectedEntity + " in " + files.keySet());

        String controllerPkg = spec.packageOf("controller");
        Path expectedController = outDir.resolve("src/main/java")
                .resolve(controllerPkg.replace('.', '/'))
                .resolve(spec.controllerClass() + ".java");
        assertTrue(files.containsKey(expectedController),
                "expected " + expectedController + " in " + files.keySet());
    }
}

