package io.github.describeadmin.codegen;

import org.junit.jupiter.api.Test;

import java.io.ByteArrayOutputStream;
import java.io.PrintStream;
import java.nio.charset.StandardCharsets;
import java.time.Duration;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTimeoutPreemptively;
import static org.junit.jupiter.api.Assertions.assertTrue;

class CodegenCliMutaGate14Test {

    @Test
    void frontendOutOptionConsumesItsValueAndParsingTerminates() {
        ByteArrayOutputStream buf = new ByteArrayOutputStream();
        PrintStream out = new PrintStream(buf, true, StandardCharsets.UTF_8);

        String[] args = {
                "definitely-missing-spec-file-for-test.yaml",
                "--frontend-out", "some-frontend-dir",
                "--dry-run"
        };

        // With the mutation (--i instead of ++i) the argument index never advances,
        // so the loop would spin forever; the timeout turns that into a failure.
        int code = assertTimeoutPreemptively(Duration.ofSeconds(5), () -> CodegenCli.run(args, out));

        String text = buf.toString(StandardCharsets.UTF_8);
        assertEquals(1, code);
        assertTrue(text.contains("Spec 文件不存在"), text);
        assertFalse(text.contains("未知参数"), text);
    }
}

package io.github.describeadmin.codegen;

import org.junit.jupiter.api.Test;

import java.io.ByteArrayOutputStream;
import java.io.PrintStream;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.atomic.AtomicReference;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

class CodegenCliMutaGate15Test {

    @Test
    void layoutOptionConsumesItsValueAndParsingTerminates() throws Exception {
        ByteArrayOutputStream buf = new ByteArrayOutputStream();
        PrintStream out = new PrintStream(buf, true, StandardCharsets.UTF_8);
        AtomicReference<Integer> result = new AtomicReference<>();
        AtomicReference<Throwable> error = new AtomicReference<>();

        String[] args = {"definitely-missing-spec-file-xyz.yaml", "--layout", "flat"};

        Thread t = new Thread(() -> {
            try {
                result.set(CodegenCli.run(args, out));
            } catch (Throwable e) {
                error.set(e);
            }
        });
        t.setDaemon(true);
        t.start();
        t.join(5000);

        // With the mutation, the argument index moves backwards and the loop never ends.
        assertFalse(t.isAlive(), "argument parsing should terminate");
        assertNull(error.get());
        assertEquals(Integer.valueOf(1), result.get());
        String text = buf.toString(StandardCharsets.UTF_8);
        assertTrue(text.contains("Spec 文件不存在"), text);
        assertFalse(text.contains("未知参数"), text);
    }
}

package io.github.describeadmin.codegen;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
