import java.nio.file.Path;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class CodegenCliMutaGate40Test {

    private static String buildSpec(String pkgKey, String type, boolean withPrefix) {
        StringBuilder sb = new StringBuilder();
        sb.append(pkgKey).append(": com.example.demo\n");
        sb.append("module: user\n");
        sb.append("entity: User\n");
        sb.append("table: sys_user\n");
        sb.append("comment: 用户\n");
        if (withPrefix) {
            sb.append("apiPrefix: /api/user\n");
        }
        sb.append("fields:\n");
        sb.append("  - name: username\n");
        sb.append("    type: ").append(type).append("\n");
        sb.append("    comment: 用户名\n");
        return sb.toString();
    }

    @Test
    void secondRunWithoutForceReportsSkippedFiles(@TempDir Path tmp) throws Exception {
        Path spec = tmp.resolve("spec.yaml");
        Path outDir = tmp.resolve("out");

        String[] pkgKeys = {"basePackage", "package"};
        String[] types = {"string", "String", "varchar"};
        boolean[] prefixes = {true, false};

        boolean ok = false;
        SpecException last = null;
        outer:
        for (String pk : pkgKeys) {
            for (String type : types) {
                for (boolean withPrefix : prefixes) {
                    Files.writeString(spec, buildSpec(pk, type, withPrefix), StandardCharsets.UTF_8);
                    ByteArrayOutputStream first = new ByteArrayOutputStream();
                    try {
                        int code1 = CodegenCli.run(
                                new String[] {spec.toString(), "--out", outDir.toString()},
                                new PrintStream(first, true, StandardCharsets.UTF_8));
                        assertEquals(0, code1);
                        ok = true;
                        break outer;
                    } catch (SpecException e) {
                        last = e;
                    }
                }
            }
        }
        if (!ok) {
            throw last;
        }

        ByteArrayOutputStream second = new ByteArrayOutputStream();
        int code2 = CodegenCli.run(
                new String[] {spec.toString(), "--out", outDir.toString()},
                new PrintStream(second, true, StandardCharsets.UTF_8));
        assertEquals(0, code2);

        String text = second.toString(StandardCharsets.UTF_8);
        assertTrue(text.contains("跳过  src/main/java"), text);
        assertTrue(text.contains("(已存在，用 --force 覆盖)"), text);
    }
}

